Lemma to_fout_star_only : forall ms model U,
  to_fout ms model U ->
  m_halted model = None ->
  m_vm_lazy model = [] ->
  forall tr c, star segs (mkCfg ms model) tr c ->
    exists o, U o /\ is_prefix tr (fout_trace o).
Proof.
