Definition fon_path (c : config) : Prop :=
  (m_halted (cfg_model c) = None
   /\ m_vm_lazy (cfg_model c) = []
   /\ exists U, to_fout (cfg_ms c) (cfg_model c) U)
  \/ m_halted (cfg_model c) <> None.

Lemma fon_path_step : forall c evs c',
