  m_halted model = None ->
  m_vm_lazy model = [] ->
  msteps segs ms ms' ->
  ms_svc_pending ms' = Some x8 ->
  syscall_spec (sys_input segs ms' x8) model Unmodeled ->
  all_traces_error segs (mkCfg ms model).
